import * as React from 'react';
import * as AnimatedSpherePrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface AnimatedSphereProps extends React.ComponentPropsWithoutRef<typeof AnimatedSpherePrimitive.AnimatedSphere> {
  className?: string;
}

export const AnimatedSphere = React.forwardRef<HTMLDivElement, AnimatedSphereProps>(
  ({ className, children, ...props }, ref) => (
    <AnimatedSpherePrimitive.AnimatedSphere
      ref={ref}
      className={clsx(
        'relative flex items-center justify-center overflow-hidden rounded-2xl bg-card border border-border p-4 shadow-sm',
        className
      )}
      {...props}
    >
      {children}
    </AnimatedSpherePrimitive.AnimatedSphere>
  )
);
AnimatedSphere.displayName = 'AnimatedSphere';

