import { AnimatedSphere } from '@exhuma/core';

class ExhumaAnimatedSphereElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-animated-sphere');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-animated-sphere')) {
  customElements.define('exhuma-animated-sphere', ExhumaAnimatedSphereElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as AnimatedSpherePrimitive from '@exhuma/core';

export interface AnimatedSphereProps extends ViewProps {
  children?: React.ReactNode;
}

export function AnimatedSphere({ style, children, ...props }: AnimatedSphereProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

